package org.circus.core;
import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Actual self-authored hidden HWND/DIB + actual GDI + core render graph.
 * No original EXE/process, game asset, engine WM_PAINT or AWT renderer. */
public final class Pc1RenderContextAudit {
 private static int count;private static void check(boolean b,String why){count++;if(!b)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{
  if(args.length!=2)throw new IOException("Require explicit window.dll and pc1_gdi.dll paths");
  Pc1WindowsWindow.NativeDispatcher standard=new Pc1WindowsWindow.NativeDispatcher(){public Pc1WindowsWindow.Dispatch dispatch(long hwnd,int message,long w,long l)throws IOException{if(message>=0x400&&message<0x8000)throw new IOException("audit has no engine dispatcher for message"+message);return Pc1WindowsWindow.Dispatch.unhandled();}public int quitFlag(){return 0;}};
  try(Pc1WindowsWindow window=new Pc1WindowsWindow(Paths.get(args[0]),standard);Pc1GdiGlyph font=new Pc1GdiGlyph(Paths.get(args[1]),window.hwnd())){
   NativeRgbImage initial=window.dibRgb();long[] handles=window.bootstrapHandles();check(handles[3]!=handles[4]&&handles[4]==handles[5],"actual unselected DIB and selected DDB retain native bootstrap distinction");check(initial.width==800&&initial.height==600&&initial.stride==2400,"explicit real DIB bytes, no guessed heap initialization");
   Pc1RenderContextTests.Fixture f=new Pc1RenderContextTests.Fixture(font,initial);f.context.drawInline(24,20,32,new byte[]{'A','B',0,0},7);NativeRgbImage first=f.context.compositor().front();check(!Arrays.equals(initial.bgr24(),first.bgr24()),"actual GDI mono outlines and native kernel change known front pixels");check(f.memory.readInt(Pc1InlineText.X)==52&&f.memory.readInt(Pc1InlineText.FONT)==28&&font.fontMemory().requestedSize()==28,"real font context and canonical inline cursor reflect current native call");check(f.context.compositor().rawDirty().left==24&&f.context.compositor().rawDirty().right==66&&f.context.compositor().invalidationSerial()==0,"actual GDI submits native dirty rectangles without implicit HWND invalidation");
   byte[] cache=f.context.glyphCache().bytes();int oldRequested=font.fontMemory().requestedSize(),oldAscent=font.fontMemory().ascent();f.context.drawInline(24,20,32,new byte[]{'A','B',0,0},7);check(Arrays.equals(cache,f.context.glyphCache().bytes())&&font.fontMemory().requestedSize()==oldRequested&&font.fontMemory().ascent()==oldAscent,"repeated direct draw uses same cache/font owner rather than fresh context");
   NativeRgbImage background=Pc1RenderContextTests.solid(800,600,0x243548);f.backend.images.put("bg",Pc1GraphicsResources.Source.rgb(background));f.context.path(0,new byte[]{'b','g'});f.context.restoreBody(0,0,800,600,0);check(Arrays.equals(background.bgr24(),f.context.compositor().front().bgr24()),"Underlay restores real typed background through same compositor and idle effect owner");
   f.host.pc1.codeBuffer().writeBytes(500,new byte[]{'T','I','T','L','E',0});f.host.pc1.uiProducer().rectangle(10,10,250,70,new byte[]{'x'});f.host.pc1.uiProducer().text(12,14,Pc1NativeMemory.CODE_BASE+500,7,99);f.context.buttons(0);NativeRgbImage rendered=f.context.compositor().front();check(!Arrays.equals(background.bgr24(),rendered.bgr24())&&f.context.compositor().invalidationSerial()==1,"raw UI→expand→Inline→actual GDI→same image produces real pixels/present journal");check(f.memory.readInt(Pc1InlineText.X)==97&&f.memory.readInt(Pc1InlineText.LENGTH)==5,"odd ASCII UI string retains native2-byte parser advance and full known shared suffix");
   byte[] rawRuntime=f.runtimeBytes(),rawRender=f.renderBytes();try(Pc1GdiGlyph nextFont=new Pc1GdiGlyph(Paths.get(args[1]),window.hwnd())){
    Pc1RenderContextTests.Fixture restored=new Pc1RenderContextTests.Fixture(nextFont,null);restored.host.pc1.load(new DataInputStream(new ByteArrayInputStream(rawRuntime)));restored.context=Pc1RenderContext.load(new DataInputStream(new ByteArrayInputStream(rawRender)),restored.host.pc1,restored.memory,nextFont,restored.backend,restored.expansion,restored.leaves);restored.connectEffects();check(Arrays.equals(rawRuntime,restored.runtimeBytes())&&Arrays.equals(rawRender,restored.renderBytes()),"actual font/cache/pool/dirty/names and canonical runtime restore exact separate owned wires");check(Arrays.equals(rendered.bgr24(),restored.context.compositor().front().bgr24())&&nextFont.snapshot().fontIdentity.equals(font.snapshot().fontIdentity),"actual GDI environment identity validates before saved rendering can resume");
    window.uploadDib(restored.context.compositor().front());check(Arrays.equals(window.dibRgb().bgr24(),rendered.bgr24()),"explicit platform transfer writes actual DIB bytes without inventing WM_PAINT");check(window.compatiblePixel(0,0)==0,"DIB upload does not silently blit to separately selected native DDB");
   }
   check(f.memory.readInt(0x4304e8)==f.context.compositor().rawDirty().left&&f.memory.readInt(0xbc5f5c)==f.context.compositor().clip().right,"actual HWND/GDI route exposes the same native dirty/clip owner");window.requireSnapshotBoundary();check(window.windowInfo()[1]==0,"audit window remains hidden");System.out.println("font="+font.environment());System.out.println("initialDibSha256="+Binary.sha256(initial.bgr24()));System.out.println("inlineActualGdiSha256="+Binary.sha256(first.bgr24()));System.out.println("uiActualGdiSha256="+Binary.sha256(rendered.bgr24()));System.out.println("runtimeSha256="+Binary.sha256(rawRuntime)+";renderSha256="+Binary.sha256(rawRender));System.out.println("Pc1RenderContextAudit PASS "+count+"; actual hidden HWND/DIB/GDI, synthetic image IO and MES; native engine WM_PAINT/window/controls producer remain separate required services");
  }
 }
}
